-- [[ filaco: a calm colorscheme generated by mini.hues ]]
--
-- `:colorscheme filaco` runs this file: Neovim looks for `colors/<name>.lua` on the
-- 'runtimepath', and the config directory is on it. `:help :colorscheme`
--
-- mini.hues builds every highlight group from two base colors. The other colors
-- (red, green, blue, ...) are picked at an even distance on the color wheel and get the
-- same lightness as the foreground, so nothing jumps out. 'saturation' sets how vivid they are; 'low'
-- is the calmest. Try other values live with `:lua require('mini.hues').setup { ... }`.
--  See `:help mini.hues` and `:help MiniHues.config`
--
-- It colors mini.nvim, which-key, gitsigns, blink.cmp and mason itself (its `plugins`
-- integrations); everything else uses the standard groups it defines.

require('mini.hues').setup {
  background = '#1c2128', -- dark blue-gray, not black
  foreground = '#c9d1d9', -- soft light gray, not white
  saturation = 'low',
}

-- `setup()` only defines highlight groups; naming them makes this a colorscheme
-- (`:colorscheme` shows it, `:Pick colorschemes` lists it). `:help g:colors_name`
vim.g.colors_name = 'filaco'
